import{_ as i,o as d,c as a,ag as t}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Admin Dashboard -> Admin Access (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/admin-access.md","filePath":"modules/admin-dashboard/admin-access.md"}'),o={name:"modules/admin-dashboard/admin-access.md"};function n(l,e,s,c,r,u){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="admin-dashboard-admin-access-deep" tabindex="-1">Admin Dashboard -&gt; Admin Access (deep) <a class="header-anchor" href="#admin-dashboard-admin-access-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Admin Access (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>admin-access</code><br><strong>Route:</strong> <code>/admin-dashboard/admin-access</code></p><p>This screen lets an admin create, view, copy, and delete admin signup links.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Create invitation links for new admins.</li><li>Persist each link with token, email, pending state, and created date.</li><li>Email the signup link to the invited person.</li><li>Remove old links from the list.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/AdminAccess.tsx</code></td><td>Route page and UI</td><td>Calls <code>GET_ALL_SIGNUP_LINKS</code>, <code>CREATE_SIGNUP_LINK</code>, <code>DELETE_SIGNUP_LINK</code>; manages local form state; uses <code>toast</code> and clipboard copy.</td></tr><tr><td><code>Frontend/src/graphql/mutations/auth.ts</code></td><td>GraphQL operations used by this screen</td><td>Defines <code>GET_ALL_SIGNUP_LINKS</code>, <code>CREATE_SIGNUP_LINK</code>, <code>DELETE_SIGNUP_LINK</code>. Also contains <code>UPDATE_SIGNUP_LINK_STATUS</code>, which belongs to the same module but is used by the signup/auth flow rather than this page.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-all-signup-links" tabindex="-1"><code>GET_ALL_SIGNUP_LINKS</code> <a class="header-anchor" href="#get-all-signup-links" aria-label="Permalink to &quot;`GET_ALL_SIGNUP_LINKS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/auth.ts</code></li><li>Query name: <code>GetAllSignupLinks</code></li><li>Returns: <code>id</code>, <code>firstName</code>, <code>lastName</code>, <code>email</code>, <code>token</code>, <code>signupDate</code>, <code>pending</code>, <code>signupLink</code></li><li>Used by: <code>AdminAccess.tsx</code> on page load</li></ul><h3 id="create-signup-link" tabindex="-1"><code>CREATE_SIGNUP_LINK</code> <a class="header-anchor" href="#create-signup-link" aria-label="Permalink to &quot;`CREATE_SIGNUP_LINK`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/auth.ts</code></li><li>Variables: <code>firstName</code>, <code>lastName</code>, <code>email</code></li><li>Backend mutation: <code>createSignUpLink</code></li><li>Used by: <code>AdminAccess.tsx</code> submit handler</li><li>On success: page refetches links and resets local form state</li></ul><h3 id="delete-signup-link" tabindex="-1"><code>DELETE_SIGNUP_LINK</code> <a class="header-anchor" href="#delete-signup-link" aria-label="Permalink to &quot;`DELETE_SIGNUP_LINK`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/auth.ts</code></li><li>Variables: <code>id</code></li><li>Backend mutation: <code>deleteSignUpLink</code></li><li>Used by: <code>AdminAccess.tsx</code> delete action</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/SignupLink/SignupLinkTypedef.js</code></li><li>Main types: <ul><li><code>SignupLink</code></li><li><code>SignupToken</code></li><li><code>DeleteResponse</code></li></ul></li><li>Query fields: <ul><li><code>getAllSignupLinks: [SignupLink!]!</code></li><li><code>getSignupTokenDetails(token: String!): SignupToken</code></li></ul></li><li>Mutation fields: <ul><li><code>createSignUpLink(firstName: String!, lastName: String!, email: String!): SignupLink!</code></li><li><code>deleteSignUpLink(id: ID!): DeleteResponse!</code></li><li><code>updateSignupLinkStatus(id: ID!, pending: Boolean!, email: String!): SignupLink!</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/SignupLink/SignupLinkResolver.js</code></li><li>Query resolvers: <ul><li><code>getAllSignupLinks</code><ul><li>Reads all signup link documents from <code>SignupToken</code></li><li>Sorts newest first by <code>signupDate</code></li></ul></li><li><code>getSignupTokenDetails</code><ul><li>Validates token exists and is still pending</li></ul></li></ul></li><li>Mutation resolvers: <ul><li><code>createSignUpLink</code><ul><li>Rejects duplicate email in signup-link collection</li><li>Generates UUID token</li><li>Builds <code>${FRONTEND_URL}/signup/${token}</code></li><li>Saves record in <code>SignupToken</code></li><li>Sends email via <code>sendOtpEmail(..., &quot;signupLinkCreation&quot;)</code></li></ul></li><li><code>deleteSignUpLink</code><ul><li>Deletes one saved link by id</li></ul></li><li><code>updateSignupLinkStatus</code><ul><li>Marks link pending/non-pending</li><li>When pending becomes false, upgrades the matching user to <code>role = &quot;Admin&quot;</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/SignupLink</code></td><td>Stores the invitation token record</td></tr><tr><td><code>server/src/models/User</code></td><td>Used when activating an invited admin</td></tr><tr><td><code>server/src/utils/SendOtpEmail.js</code></td><td>Sends the signup-link email</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens <code>AdminAccess.tsx</code>.</li><li><code>useQuery(GET_ALL_SIGNUP_LINKS)</code> loads all saved invite links.</li><li>Admin submits first name, last name, and email.</li><li><code>CREATE_SIGNUP_LINK</code> calls <code>createSignUpLink</code>.</li><li>Backend creates token, saves the record, sends the email, and returns the created link.</li><li>Frontend refetches and shows the new row.</li><li>Delete action calls <code>DELETE_SIGNUP_LINK</code>; backend removes the record; frontend refetches.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The screen imports its query from <code>mutations/auth.ts</code>; the file is mixed-purpose and contains both queries and mutations.</li><li><code>updateSignupLinkStatus</code> is part of the same backend module, but it is not triggered from this admin page. It is used later in the signup/auth flow when the invited account completes onboarding.</li></ul>',25)])])}const m=i(o,[["render",n]]);export{p as __pageData,m as default};
